(9666, 'tLCLxt!!', 'Shackle', 'Adds some weight to your kicks. Perfect not only for weaponry, but for looking like a convicted felon!', NULL, 0, 0, 0, 0, 20, 0, 0, -3, -3, 0, 0, 0, 0, '', '', 'footwearkind', '', 'average', '', '', 'Build_Grist:16|Rust:16|', '', 'not a statement', 1),
(9667, 'H0m312un', 'Baseball Bat', 'Commonly used to deflect small leather balls, aiming to send them sky high.', '', 1, 0, 0, 0, 4, 0, 0, 0, 0, 0, 0, 0, 0, 'baseballbatcard.png', 'undulatingCaptain', 'sportskind, clubkind', 'none', 'average', '', '', 'Build_Grist:3|', '', 'dont forget the PBNJ', 0),
(9668, 'wPD!!Nw!', 'Chester\\\'s Long Coat', 'This exquisitely sewn aristocratic suit allows its wearer to move in silence, lending well to stealth.', NULL, 0, 0, 0, 0, 5, 0, 0, 15, 0, 0, 0, 0, 0, '', '', 'notaweapon', ' bodygear', 'average', '', '', 'Build_Grist:50|Blood:100|Jet:150|', '', 'not a statement', 1),
(9669, '8N0G075k', 'Equestrian\\\'s Handbook', 'Unruly stallion? Claim mastery over your steed with this handy, easy-to-read tome.', NULL, 0, 0, 0, 0, 40, 0, 0, 0, 0, 0, 0, 0, 0, 'equestrianshandbook.png', 'apocalypseGambit', 'bookkind', '', 'average', '', '', 'Build_Grist:80|Amber:60|Garnet:30|', '', 'not a statement', 1),
