(9877, 'hxd!?V?!', 'Shinigami Guitar', 'A guitar with grim reaper motif. Black, emblazoned with a skull and scythe. It seems to be accompanied by a strange background noise every time a string is plucked. This gives new meaning to the term \"death metal\".', NULL, 0, 0, 0, 0, 201, 0, 0, 0, 0, 0, 0, 0, 0, 'shinigamiguitarcard.png', 'unseenMaestro', 'stringskind', '', 'large', '', '', 'Build_Grist:33000|Caulk:13000|Jet:43000|', '', 'not a statement', 1),
(9878, '422LW02W', 'Magic Stick', 'You\'re not too sure how magical this thing actually is, but it looks decent for hitting things. Amusingly, despite the magic being strictly of the \"whacky\" variety, your strife specibus still considers it a wand.', NULL, 0, 0, 0, 0, 42, 0, 0, 0, 0, 0, 0, 0, 0, '', '', 'wandkind', '', 'average', '', '', 'Build_Grist:20|Emerald:15|', '', 'not a statement', 1),
