(10004, 'WL0GAkez', 'Lug Wrench', 'When you need to lug your nuts, this is the wrench for you.', NULL, 0, 0, 0, 0, 5, 0, 0, 0, 0, 0, 0, 0, 0, '', '', 'toolkind', '', 'average', '', '', 'Build_Grist:10|Copper:4|', '', 'not a statement', 1),
(10005, 'e3004X05', 'Destroyer Cannon', 'An experimental rifle made with salvaged technology from The Destroyer. I wonder what it does...?', NULL, 0, 0, 0, 0, 4000, 0, 10, 0, 0, 0, 0, 0, 0, '', '', 'riflekind', '', 'average', '', '', 'Emerald:250000|Opal:55000|Shale:150000|', '', 'not a statement', 1),
(10006, 'h2PHjW9X', 'Lil\\\' Spitfire', 'Perfect for the playful arson in you. Strike down enemies with the hot gyrating inferno produced by the spin of this tricked out yo-yo. The sharp thorns on it only add insult to injury, or in this case, injury to injury.', NULL, 0, 0, 0, 0, 85, 0, 0, 0, 3, 0, 0, 2, 0, '', '', 'yoyokind', '', 'average', '', '', 'Build_Grist:1000|Redstone:500|Sunstone:2000|', '', 'not a statement', 1),
(10007, '00AK08p?', 'Megaton Hammer', '\"A long time ago there was an evil dragon named Volvagia living in this mountain. That dragon was very scary! He ate Gorons! Using a huge hammer, the hero of the Gorons... BOOOM! Destroyed it just like that.\"', NULL, 0, 0, 0, 0, 500, 0, 0, 0, 0, 0, 0, 0, 0, 'megatonhammer.png', 'Tribor', 'hammerkind', '', 'average', '', '', 'Build_Grist:50000|Obsidian:5000|Quartz:1|Titanium:15000|', '', 'not a statement', 1);
