(10396, 'P81GOOOG', 'MAD NASTY B00ST THUG TRIKKIN Claus', 'Rockets, skateboards and holiday icons have never been so deadly.', NULL, 0, 0, 0, 0, 543, 6, 60, 60, 60, 60, 60, 60, 6, '', '', 'fancysantakind, skatekind', '', 'average', '', '', 'Amber:74000|Ruby:25000|', '', 'not a statement', 1),
(10397, '9G4KMbG9', 'Slimy Sock Puppet', 'Oh no, someone\'s covered your poor little sock pal with nasty gunk of a paranatural sort. Oh wait, that was YOU.', NULL, 0, 0, 0, 0, 7, 0, 0, 0, 0, 0, 0, 0, 0, 'slimysockpuppetcard.png', 'Caellus Slag', 'puppetkind', '', 'average', '', '', 'Build_Grist:2|Cobalt:9|', '', 'not a statement', 1),
(10398, '?RKTs?VF', 'Well-Dressed Marionette', 'Now your strung-up little buddy is ready for the puppet prom.', NULL, 0, 0, 0, 0, 12, 0, 0, 0, 0, 0, 0, 7, 7, 'welldressedmarionette.png', 'Hostile', 'puppetkind', '', 'average', '', '', 'Build_Grist:40|Tar:10|', '', 'not a statement', 1),
(10399, 'TEUTMbU!', 'Bearly Dangerous', 'The classic stuffed teddy just got twice as manipulative. Impress your friends/enemies/inlaws with this cuddly bear puppet!', NULL, 0, 0, 0, 0, 19, 0, 0, 0, 0, 0, 0, 0, 0, '', '', 'puppetkind, toykind', '', 'average', '', '', 'Build_Grist:44|Iodine:33|', '', 'not a statement', 1),
