(11504, 'xUVRx!?l', 'Jack-In-The-Box', 'A somewhat harmless joke toy meant to open up and surprise you with a clown. You consider using it to build your Prankster\'s Gambit.', NULL, 0, 0, 0, 0, 50, 0, 0, 0, 0, 0, 0, 0, 5, 'jackinthebox.png', 'apocalypseGambit', 'toykind', '', 'large', '', '', 'Build_Grist:5000|Frosting:500|Marble:1000|', '', 'not a statement', 1),
(11505, 'xUVVx!?l', 'Die-In-The-Box', 'This toy has been modified to shoot dice out instead of a clown: making it sightly more of a choke hazard than what you\'d normally get out of a toy store.', NULL, 0, 0, 0, 0, 540, 20, 0, 0, 0, 0, 0, 0, 20, '', '', 'dicekind', '', 'large', '', '', 'Build_Grist:50000|Frosting:1|Rock_Candy:50000|Shale:50000|Tar:50000|', '', 'not a statement', 1),
