(11683, 'W00a00Ba', 'No Okami', 'A sword fallen through the very cracks of Heaven, a sword that has no rival. The Circular hilt represents the world and all that it can destroy. This weapon should only belong in the hands of the god who gives life to all. A blade worthy of being claimed by Izanagi.', NULL, 0, 0, 0, 0, 9999, 3500, 3500, 3500, 3500, 3500, 3500, 3500, 3500, '', '', 'bladekind', '', 'large', '', '', 'Copper:450000|Diamond:300000|Polychromite:360000|Quartz:100000|Redstone:600000|', '', 'not a statement', 1),
(11684, 'c14b11Ba', 'Myriad Truths', '\"I am thou, and thou art I...  From the sea of thy soul, I come... I giveth thee the power to shine light upon your allies... And bringeth to vision the path to the truth.\"', NULL, 0, 0, 0, 0, 9999, 9999, 9999, 9999, 9999, 9999, 9999, 9999, 9999, '', '', 'bladekind', '', 'large', '', '', 'Build_Grist:25000000|Copper:10000000|Diamond:1562500|Gold:6250000|Polychromite:12000500|Sunstone:15000000|Topaz:3125000|', '', 'not a statement', 1),
(11685, '0000000W', 'Thousand Lies', '\"I am thou, and thou art I...  From the sea of thy soul, I come... I grant upon thee the power to cloud the judgement of thine enemies... And bring forth the fog that shall shroud the truth.\"', NULL, 0, 0, 0, 0, 9999, 9999, 9999, 9999, 9999, 9999, 9999, 9999, 9999, '', '', 'pistolkind', '', 'large', '', '', 'Build_Grist:30000000|Copper:20000000|Jet:8000000|Quartz:6250000|Redstone:4000000|Rust:3125000|Star_Sapphire:7000000|', '', 'not a statement', 1),
