(12416, '!l!t!!z!', 'The Claws of Bastet', 'Bestowed with the powers of an Eye of Ra, these claws burn like the sun and are perfect for protecting those in need.', NULL, 0, 0, 0, 0, 5000, 0, 0, 0, 450, 0, 0, 0, 0, '', '', 'clawkind', '', 'average', '', '', 'Diamond:25000|Garnet:35000|Ruby:50000|Sunstone:100000|', '', 'not a statement', 1),
(12417, '20GD4W02', 'Giga Drill Breaker', 'An incredibly powerful drill, clearly capable of digging upwards and through the very heavens.', NULL, 0, 0, 0, 0, 35, 0, 4, 5, 6, 0, 3, 2, 1, '', '', 'diggerkind', '', 'average', '', '', 'Build_Grist:100|Titanium:50|', '', 'not a statement', 1),
