(12861, 'lyzdRLVx', 'Puffy Thundercloud Studbumpers', 'Crackling with electricity and studded with charged metal spikes, these gloves give you a punch that rivals the might of Zeus himself!', NULL, 0, 0, 0, 0, 777, 0, 77, 0, 33, 0, 33, 0, 77, '', '', 'inflatablekind, glovekind', '', 'large', '', '', 'Build_Grist:100000|Amber:177777|Caulk:33333|Titanium:7373|', '', 'not a statement', 1),
(12862, 'B2XKdIO3', 'Squeak Chop', 'Introducing... Squeak Chop! The latest in inflatable mealtime hammer technology that grinds your ingredients and enemies into powder with every smash! Want to spice up your strifes AND your supper at the same time? Then the Squeak Chop is for you!', NULL, 0, 0, 0, 0, 1999, 0, 0, 100, 100, 100, 100, 0, 0, '', '', 'inflatablekind, hammerkind', '', 'large', '', '', 'Build_Grist:499999|Malachite:399999|Rock_Candy:299999|Sulfur:99999|', '', 'not a statement', 1),
