(12924, 'imifRSiD', 'Union Jack', 'The Union Jack is the flag of the U.K, by the way. Learnin\' you some knowledge here.', '', 1, 0, 0, 0, 2, 0, 0, 0, 0, 0, 0, 0, 0, '', '', 'flagkind', 'none', 'average', '', '', 'Build_Grist:10|', '', 'Aszx@E?MLG/byEZZZZZZZZZNIZva', 0),
(12925, 'ivyf!?jj', 'Alternian Empire Flag', 'A flag bearing the insignia of Her Imperious Condescension, sure to strike fear into the population of any civilized planet. And even if the flag itself doesn\'t scare your opponents, the fearsome spikes on the end of the flagpole surely will.', NULL, 0, 0, 0, 0, 381, 0, 11, 12, 13, 0, 0, 0, 0, '', '', 'flagkind, spearkind', '', 'large', '', '', 'Blood:24000|Chalk:24000|Garnet:12612|', '', 'not a statement', 1),
