(12959, '18g0C04G', 'Umbrella Dress', 'By pushing a slide on the back of this dress, you can poof out the bottom! Varies between short and wide to long and thin.', NULL, 0, 0, 0, 0, 2, 0, 0, 0, 0, 0, 1, 5, 10, '', '', 'notaweapon', ' bodygear', 'large', '', '', 'Build_Grist:150|Chalk:15|', '', 'not a statement', 1),
(12960, 'uf!zn7xk', 'Nintendo Dicecube', 'You\'re pretty sure that rolling this will eliminate any chance of the thing playing Super Mario Sunshine, but it\'s still heavier than the dice you alchemized it from.', NULL, 0, 0, 0, 0, 32, 4, 0, 0, 0, 4, 0, 0, 0, 'nintendodicecube.png', 'Caellus Slag', 'gamekind, dicekind, entertainmentkind', '', 'average', '', '', 'Build_Grist:250|Amethyst:250|', '', 'not a statement', 1),
(12961, 'k!KFzbl!', 'Sunglasses of the Stampede', 'Sweet! These sunglasses make you look like Vash the Stampede-- VASH THE STAMPEDE!?', NULL, 0, 0, 0, 0, 2, 0, 0, -5, -5, 0, 0, 5, 5, '', '', 'notaweapon', ' facegear', 'average', '', '', 'Amber:20|Topaz:10|', '', 'not a statement', 1),
