(13048, '12101504', 'Afro Ring', 'A ring with a tiny Afro where the gem is supposed to go.', NULL, 0, 0, 0, 0, 2, 0, 0, 0, 0, 0, 0, 0, 0, '', '', 'notaweapon', 'accessory', 'average', '', '', 'Build_Grist:10|Amber:1|', '', 'not a statement', 1),
(13049, '012MX03I', 'Clawed Sledgehammer', 'A hammer with a large head and two sharp prongs on one side.', NULL, 0, 0, 0, 0, 13, 0, 0, -1, -2, 0, 0, 0, 0, '', '', 'hammerkind', '', 'large', '', '', 'Build_Grist:20|', '', 'not a statement', 1),
(13050, 'ztwlRGtR', 'Chakram', 'A hoop-like bladed weapon. Best for when you are pretending to be Xena, the Warrior Princess.', NULL, 0, 0, 0, 0, 12, 0, 0, 0, 3, 0, 0, 0, 0, '', '', 'hoopkind, ninjakind', '', 'average', '', '', 'Build_Grist:10|Rust:5|', '', 'not a statement', 1),
(13051, 'rNIWQ0MP', 'Hula Chakram', 'A large bladed hoop you can swing around your hips.', NULL, 0, 0, 0, 0, 18, 0, 0, 0, 3, 0, 3, 0, 0, '', '', 'hoopkind, ninjakind', '', 'large', '', '', 'Build_Grist:25|Rust:15|', '', 'not a statement', 1),
(13052, 'I8E5ElxZ', 'Microphone Stand', 'You\'ve recently discovered that this stand is just as useful for clubbing imps as it is for holding your sound-recording equipment.', '', 1, 0, 0, 0, 3, 0, 0, 0, 0, 0, 0, 0, 0, '', '', 'staffkind', 'none', 'average', '', '', 'Build_Grist:2|', '', 'This Xi&MbjHHGeGUAJV thinks memes are still m?YE@a=V', 0),
(13053, '!TTd?ol!', '3D Sunglasses', 'You have no idea why you made this, although it does appear to have an identity crisis with the ironically purposed sunglasses and the already purposed 3D glasses.', NULL, 0, 0, 0, 0, 1, 0, 0, 0, -1, 0, 0, 0, 0, '3dsunglasses.png', 'callibratedAttorney', 'notaweapon', ' facegear', 'average', '', '', 'Build_Grist:3|Cobalt:1|Jet:2|Ruby:1|', '', 'not a statement', 1);
