(15782, 'l??E!kLU', 'Perforating Raydent of Light', 'You can \"zap\" AND \"pap\" your enemies with this new, improved Raydent. By \"pap,\" of course, we mean fill with tiny holes.', NULL, 0, 0, 0, 0, 9999, 4000, 4000, 4000, 4000, 4000, 4000, 4000, 4000, '', '', 'staffkind, forkkind', '', 'large', '', '', 'Gold:4654335|Polychromite:1959720|Ruby:4082750|Sunstone:5634195|Topaz:4082750|Uranium:4409370|', '', 'not a statement', 1),
(15783, '!JSz!b!!', 'Chain of Nightmares', 'For your ghosts, ghouls, and generally otherworldly needs.', NULL, 0, 0, 0, 0, 47, 0, 0, 0, 0, 0, 0, 0, 0, '', '', 'chainsawkind', '', 'large', '', '', 'Build_Grist:160|Blood:135|Jet:58|', '', 'not a statement', 1),
