(16128, 'CO84GKW0', 'CGI Archer\\\'s Bow', 'Combining the latest portable 3D gaming technology with a weapon has made a barely useful version of a bow.', NULL, 0, 0, 0, 0, 13, -13, -13, -13, -13, -13, -13, -13, 13, '', '', 'bowkind', '', 'large', '', '', 'Artifact:-13|', '', 'not a statement', 1),
(16129, 'gtvbsS?Z', 'Encyclopedia of Creepypastas', 'A compilation of every creepypasta ever written. Includes pictures of scary gifs to go with each story! Perfect for scaring Imps to death or driving them mad!', NULL, 0, 0, 0, 0, 25, 0, 0, 0, 0, 0, 0, 0, 0, '', '', 'bookkind', '', 'average', '', '', 'Build_Grist:10|Chalk:10|Obsidian:5|', '', 'not a statement', 1),
