(16570, 'a0LX101b', 'Cardboard Fedora', 'A fedora made from folded cardboard. Whoever\'s idea was this was obviously a master genius.', NULL, 0, 0, 0, 0, 2, 0, 0, 0, 0, 0, 0, 0, 0, '', '', 'notaweapon', ' headgear', 'average', '', '', 'Build_Grist:5|', '', 'not a statement', 1),
(16571, 'bA112K8f', 'Gas-Fedora', 'When you thought your fedora couldn\'t be more classy, you were wrong. Putting a gas filter and a mask on it was the best idea you had in your whole life. Now it can protect your head AND your face.', NULL, 0, 0, 0, 0, 7, 0, 0, 0, 0, 0, 0, -2, 0, '', '', 'notaweapon', ' headgear', 'large', '', '', 'Jet:2|Tar:20|', '', 'not a statement', 1),
