(16761, '002KfemS', 'Electro Hammer', 'A hammer that uses a small electronic motor to boost its speed and power. Conveniently, this makes it easier to wield, but only slightly.', NULL, 0, 0, 0, 0, 16, 0, 0, -1, -2, 0, 0, 0, 0, '', '', 'hammerkind', '', 'large', '', '', 'Build_Grist:20|Rust:15|', '', 'not a statement', 1),
(16762, 'U1tqzhuz', 'Jack Hammer', 'An electro-mechanical tool that combines a hammer directly with a chisel to create a destructive weapon.', NULL, 0, 0, 0, 0, 30, 0, 0, 0, 0, 0, 0, 0, 0, '', '', 'toolkind', '', 'large', '', '', 'Build_Grist:50|Mercury:15|Redstone:20|Rust:50|', '', 'not a statement', 1),
(16763, 'fHAjeHMI', 'Sugar Scope Sniper (N)', 'Pretty, pink and brought to you by the makers of your favorite game console, this electrically powered sniper rifle is for the agile, on the go gunman who just wants to have fun.', NULL, 0, 0, 0, 0, 50, 15, 0, 0, 0, 10, 0, 0, 0, '', '', 'riflekind', '', 'large', '', '', 'Frosting:324|Marble:108|Rose_Quartz:36|Titanium:12|', '', 'not a statement', 1),
