(17019, 'ktBy?pk!', 'Murderous Gravy Boat', 'A frying pan patterned with smiley faces and letter \'E\'s. Whether cooking or fighting, this pan emits a foul purple miasma instead of smoke.', NULL, 0, 0, 1, 0, 15, 0, 0, 0, 7, 0, 0, 0, 0, '', '', 'pankind', '', 'average', '', '', 'Build_Grist:33|Copper:33|', '', 'not a statement', 1),
(17020, 'jx5r3D4T', 'Dragonborn Armor', 'As you wield the armor of the mighty Dovahkiin, you feel... YOU FEEL... pretty weighted down, actually.', NULL, 0, 0, 1, 0, 30, 0, 0, 0, 0, 5, 5, 5, 5, '', '', 'notaweapon', ' bodygear', 'large', '', '', 'Build_Grist:2500|Polychromite:50|Shale:500|Titanium:1000|', '', 'not a statement', 1),
