(18165, '?o!yzcoU', 'A Clockwork Orange', 'Provided your improvised Russian is good enough, reading this novella aloud will cause your enemies to tremble and experience nausea.', NULL, 0, 0, 0, 0, 100, 0, 0, 0, 0, 0, 0, 0, 0, '', '', 'bookkind ', '', 'average', '', '', 'Amber:290|Blood:75|Rust:950|Tar:365|', '', 'not a statement', 1),
(18166, 'iP3?1Lxk', 'Ultimate Freezing Ray', 'If you ever wanted a ray capable of freezing enemies to death, here you have it.', NULL, 0, 0, 0, 0, 9999, 9999, 9999, 9999, 9999, 9999, 9999, 9999, 9999, '', '', 'sciencekind', '', 'large', '', '', 'Build_Grist:10000000|Chalk:5000000|Cobalt:5000000|Diamond:5000000|Frosting:5000000|Opal:5000000|Quartz:5000000|Star_Sapphire:5000000|Titanium:5000000|Uranium:5000000|', '', 'not a statement', 1),
