(18213, '00308A01', 'Red Dry-Erase Marker', 'A marker used for writing and drawing on dry-erase boards, drawing boards, and the like. Can also be used to doodle embarrassing things onto the faces of your enemies and friends alike.', NULL, 0, 0, 0, 0, 30, 0, 0, 0, 0, 0, 0, 0, 0, 'RedDryEraseMarker.png', 'lordSoth', 'penkind', '', 'average', '', '', 'Build_Grist:55|Blood:55|Malachite:55|', '', 'not a statement', 1),
(18214, 'j!3s2NOt', 'Seraphic Autohunter', 'A gleaming white weapon, this Seraphic gunbow is made of a bow attached to the barrel of a gun. Just one press of the diamond trigger and dozens of gleaming white and gold arrows are launched towards the forces of darkness. ', NULL, 0, 0, 0, 0, 3000, 400, 400, 400, 400, 200, 200, 200, 200, '', '', 'automatickind, bowkind', '', 'large', '', '', 'Diamond:325000|Opal:345000|Rainbow:330000|Redstone:315000|Titanium:350000|', '', 'not a statement', 1),
