(18218, 'I24VHg0K', 'Tron Shirt', 'A white T with the futuristic TRON logo pressed on it in glow-in-the-dark ink.', NULL, 0, 0, 0, 0, 3, 0, 0, 0, 0, 0, 1, 1, 1, '', '', 'notaweapon', ' bodygear', 'average', '', '', 'Build_Grist:30|Cobalt:20|', '', 'not a statement', 1),
(18219, 'xvVlhpwS', 'Oar Naw', 'This executioner\'s ax makes you think whether oar not you are making the right choice. also let\'s you row', NULL, 0, 0, 0, 0, 8, 0, 0, 0, 0, 0, 0, 0, 0, '', '', 'axekind, oarkind', '', 'large', '', '', 'Build_Grist:20|Rust:12|', '', 'not a statement', 1),
