(19197, 'X0000000', 'Dual Bladed Keytar', 'It\'s a keytar with double edged blade for a keyboard. Yep, a dangerous keytar.', NULL, 0, 0, 0, 1998, 400, 0, 0, 25, 0, 0, 0, 0, 2, '', '', 'keykind, percussionkind, knifekind', 'none', 'average', '', '', 'Build_Grist:41730|Cobalt:41730|Jet:41730|Shale:41730|Sulfur:41730|Tar:41730|', '', 'not a statement', 0),
(19198, 'X0Z110u0', 'Wayward\'s metaspork ', 'Forged in the fires of meta hell, when a zillion forth walls breaking at the same time! When two zillion deadpools died all when a trizillion planets aligned in the quadzillionth planet in the quinzillionth day of the sexzillionth eclipse to end all meta eclipses! The illuminati\'s lord of the  apocalypse (aka the lord of heart himself) and creator of the sporkkind strife specibus himself! The skeleton, the myth, the legend himself: Wayward Joestar created one last weapon! \r\n\r\nThe last of his teachings!\r\nI present to you:\r\n\r\nWayward\'s metaspork! Use it wisely. It\'s too bad that sporkkind is not an actual specibus. Whatever...', NULL, 0, 0, 0, 2200, 300, 0, 0, 0, 20, 20, 0, 0, 0, '', '', 'metakind, forkkind', 'none', 'large', '', '', 'Build_Grist:5797|Frosting:58|Opal:5797|Plasma:5797|Polychromite:5797|Rainbow:5797|Rock_Candy:58|', 'Must have a glitch effect if it is being finalized.', 'not a statement', 0),
(19199, 'x2x3x2x2', 'Wayward\'s metaspork^2', 'SOMEHOW you found a way to make this eve more powerful! It looks the same, it is just twice as powerful, that\'s all. Wayward would be impressed.', NULL, 0, 0, 0, 2200, 640, 0, 0, 0, 40, 40, 0, 0, 0, '', '', 'metakind, forkkind', 'none', 'large', '', '', 'Build_Grist:30685|Frosting:30685|Opal:30685|Plasma:30685|Polychromite:30685|Rainbow:30685|Rock_Candy:30685|', 'Needs a x2 glitch effect.', 'not a statement', 0),
(19200, 'AgAdFA4E', 'Disk Launcher Guitar', 'Your sound is now so powerful, it launches deadly shurikens at your enemies! Yeah baby! Rock&roll!', NULL, 0, 0, 0, 292, 70, 1, 0, 0, 4, 1, 0, 0, 2, '', '', 'launcherkind, stringskind', 'none', 'large', '', '', 'Build_Grist:1305|Shale:522|Silicon:261|', '', 'not a statement', 0),
(19201, 'A8020204', 'Electric Oar Launcher Guitar', 'One chord from this guitar will make your enemies feel like they\'ve been bashed by an oar! An electric oar! How is it different from a regular oar? Well... ask them?', NULL, 0, 0, 0, 292, 167, 0, 0, 0, 10, 5, 0, 0, 5, '', '', 'oarkind, stringskind, launcherkind', 'none', 'large', '', '', 'Build_Grist:10304|Shale:2061|Silicon:1030|', '', 'not a statement', 0);
