(19334, 'e8H9282K', 'Barbed Shield of Flaming Justice', '\'Murica.', NULL, 0, 0, 0, 1991, 9999, 0, 0, 0, 0, 0, 0, 0, 0, '', '', 'notaweapon', 'none', 'average', '', '', 'Blood:3511256826|', '', 'not a statement', 0),
(19335, 'W811282G', 'Stick of Moderator\'s Justice', 'An entirely transparent stick which lets out a fearsome roar when you hit something. Also is seemingly ridiculously heavy-hitting for a small rod. Something tells you that its power isn\'t just derived from its physicality...', NULL, 0, 0, 0, 1991, 9999, 216, 0, 0, 512, 512, 0, 0, 216, '', '', 'cuekind, metakind, everythingkind', 'none', 'average', '', '', 'Artifact:542437113|', '', 'not a statement', 0),
(19336, '0H53GG2x', 'The Overseer\'s Guide to [CENSORED]', 'Uh... wow, that sure is a \"hunk rumpus effect with a triple-x stacked modifier\" on it. ...You are almost certain the Overseer wrote this.', NULL, 0, 0, 0, 2302, 10, 0, 0, 0, 0, 5, 0, 0, 0, '', '', 'bookkind', 'none', 'average', '', '', 'Aquamarine:19|Build_Grist:51|Iodine:32|', 'Sorry, Overseer', 'not a statement', 0),
(19337, 'fVBz?!R!', 'Blackest Magic Blade', 'The spirits now speak eldrich. Weather is fine tho. ', NULL, 0, 0, 0, 2290, 1900, 0, 0, 0, 0, 0, 0, 0, 0, '', '', 'bladekind', 'none', 'average', '', '', 'Blood:284710|Build_Grist:569421|Jet:2847103|Rust:113884|', '', 'not a statement', 0),
