(19354, 'gDNjmykd', 'Derse Bladed Fan', 'A black fan with purple lace, and incredibly sharp blade bits shaped like miniature Derse towers.', NULL, 0, 0, 0, 2243, 116, 0, 0, 0, 0, 0, 0, 0, 0, '', '', 'fankind', 'none', 'average', '', '', 'Build_Grist:1737|Obsidian:174|Shale:1737|', 'It can be changed however the devs want. I\'m gonna try and make an image for it.', 'not a statement', 0),
(19355, '500G0002', 'Aperture Science Fuck Gravity Broom', 'This broom comes equip with a Personality Core. This one\'s personality can bee summed up in two words: Fuck Gravity', NULL, 0, 0, 0, 238, 700, 50, 50, 50, 50, 35, 0, 0, 0, '', '', 'broomkind', 'none', 'large', '', '', 'Build_Grist:41016|Cobalt:6836|Copper:13672|Diamond:6836|Gold:6836|Rust:13672|Silicon:13672|Titanium:13672|Wood:6836|', '', 'not a statement', 0),
(19356, '900n00A1', 'Reaper with a Gun', 'Now death can hit you with his experimental scythe shooter. If avoiding him wasn\'t hard enough he now has a railgun. Goodluck.', NULL, 0, 0, 0, 1876, 3746, 0, 0, 300, 300, 300, 300, 0, 0, '', '', 'riflekind, scythekind', 'none', 'large', '', '', 'Blood:1058867|Build_Grist:3529555|Lead:529433|', '', 'not a statement', 0),
(19357, '1c0?W914', 'Kwami Caduceus', 'These needles are used to sew the suits of Miraculous wielders.Those things don\'t make themselves ', NULL, 0, 0, 0, 223, 49, 0, 0, 0, 0, 0, 0, 0, 0, '', '', 'needlekind', 'none', 'average', '', '', 'Amethyst:837|Build_Grist:1674|Shale:2510|', '', 'not a statement', 0),
