(19889, '2282900s', 'Scotsman\'s Skullcutter', '(To be read in a Scottish accent) When a man in old Scotland needs a head to be cut clean off, there only be one choice for the job t\' get done.', '', 0, 0, 0, 0, 130, 0, 0, 10, 10, 10, -10, -10, -20, '', '', 'axekind', 'none', 'large', '', '', 'Build_Grist:5000|Blood:1|Wood:100|Iron:5000|Titanium:1000|', '', 'KU^PHpAUkXHO? has a big grin on its face.', 0),
(19890, 'pXElJmw!', 'Nightmare Headhunter', 'With this axe, you can put someone to sleep briefly for them to have a nightmare about their head getting chopped off. They\'ll be so terrified they\'ll wake up immediately, which will promptly be followed by you actually chopping their head off.', '', 0, 0, 0, 0, 500, 0, 0, 0, 0, 0, 0, 0, 0, '', '', 'axekind', 'none', 'large', '', '', 'Build_Grist:10000|Obsidian:10000|', '', 'Lxnf/BQ$TEzLXz#^q', 0),
