  `suspended` tinyint(1) NOT NULL DEFAULT '0',
  `randomized` tinyint(1) NOT NULL DEFAULT '0' COMMENT 'The submission recipe came from the randomizer',
  `halp` tinyint(1) NOT NULL DEFAULT '0' COMMENT 'Flag indicating a higher-up should deal with this',
  `lastupdated` bigint(20) NOT NULL DEFAULT '-1' COMMENT 'Timestamp at which the last change was made to this submission (creation, comment, or edit)',
  `bonuses` longtext NOT NULL,
  `grists` longtext NOT NULL,
  `abstratus` varchar(200) NOT NULL,
  `wearable` varchar(100) NOT NULL,
  `size` varchar(16) NOT NULL,
  `consumable` tinyint(1) NOT NULL,
  `catalogue` tinyint(1) NOT NULL,
  `lootonly` tinyint(1) NOT NULL,
  `refrance` tinyint(1) NOT NULL
) ENGINE=MyISAM DEFAULT CHARSET=latin1 COMMENT='Stores feedback submitted by players';

