--
-- Table structure for table `strifers`
--

CREATE TABLE `strifers` (
  `id` bigint(20) NOT NULL COMMENT 'semi-permanent ID of strifer for things like sprite reference',
  `name` varchar(100) NOT NULL COMMENT 'strifer',
  `owner` int(11) NOT NULL DEFAULT '0' COMMENT 'ID of character who "owns" this strifer. Nonzero for actual characters and persistent allies like sprites or mercenaries. If zero, strifer will be deleted at the end of strife.',
  `strifeid` bigint(20) NOT NULL DEFAULT '0' COMMENT 'ID of battle this strifer is currently in',
  `side` tinyint(4) NOT NULL DEFAULT '0' COMMENT 'what side this strifer''s on, usually 0 if on player''s side and 1 if enemy (but there can be more than 2 sides)',
  `leader` tinyint(1) NOT NULL DEFAULT '0' COMMENT '1 if this strifer is the strife leader. That basically just means they press the "execute this round" button',
  `teamwork` int(4) NOT NULL COMMENT 'Teamwork rating for this strifer. Base values only go up to 100, but this can be exceeded',
  `control` tinyint(1) NOT NULL DEFAULT '0' COMMENT '1 if player can control this strifer, 0 if not',
  `grist` varchar(20) NOT NULL DEFAULT 'None' COMMENT 'grist type, added to the front of the enemy name if not "None"',
  `land` tinyint(4) NOT NULL COMMENT 'land grist ID of enemy''s origin',
  `description` longtext NOT NULL COMMENT 'strifer''s description',
  `echeladder` int(4) NOT NULL COMMENT 'Echeladder height of this strifer. Mostly relevant to player roletechs.',
  `aspect` varchar(15) NOT NULL COMMENT 'Strifer''s Aspect designation, if any.',
  `fatigue` int(5) NOT NULL DEFAULT '0' COMMENT 'This strifer''s fatigue. Is set when they join strife, NOT maintained on the strife row in any way.',
  `power` int(11) NOT NULL COMMENT 'current power level of strifer',
  `maxpower` int(11) NOT NULL COMMENT 'max power of strifer',
  `health` int(11) NOT NULL COMMENT 'remaining health of strifer',
  `maxhealth` int(11) NOT NULL COMMENT 'max health of strifer',
  `energy` int(11) NOT NULL COMMENT 'remaining energy (aspect vial) of strifer',
  `maxenergy` int(11) NOT NULL COMMENT 'max energy (aspect vial) of strifer',
  `luck` int(5) NOT NULL DEFAULT '0' COMMENT 'Luck value for this strifer. Stored separately since it will need to be referenced at odd times.',
  `brief_luck` int(4) NOT NULL DEFAULT '0' COMMENT 'Holds luck boosts that will last for the current strife only',
  `subaction` tinyint(1) NOT NULL DEFAULT '0' COMMENT 'whether or not strifer has used an extra action (consumable, roletech, etc) this round',
  `currentmotif` text NOT NULL COMMENT 'Currently active fraymotif on this strifer',
  `currentmotifname` text NOT NULL COMMENT 'Stores the name of the current fraymotif',
  `motifsused` text NOT NULL COMMENT 'Fraymotifs used by this strifer during the current strife',
  `teammotif` tinyint(1) NOT NULL DEFAULT '0' COMMENT '0 if no teammate has used a fraymotif yet this round. 1 if they have.',
  `lastactive` varchar(10) NOT NULL DEFAULT 'AGGRIEVE' COMMENT 'last active action',
  `lastpassive` varchar(10) NOT NULL DEFAULT 'ABUSE' COMMENT 'last passive action',
  `autopilot` tinyint(1) NOT NULL DEFAULT '0' COMMENT 'if 1, strifer cannot accept input from the player',
  `autoassist` int(11) NOT NULL DEFAULT '0' COMMENT 'strifer ID that this strifer will auto-join in battle',
  `noassist` tinyint(1) NOT NULL DEFAULT '0' COMMENT 'if 1, strifer cannot be joined in battle',
  `cantabscond` tinyint(1) NOT NULL DEFAULT '0' COMMENT 'if 1, strifer cannot escape',
  `ondeath` longtext NOT NULL COMMENT 'Stuff that happens on death. This is mostly loot tags but could be expanded to include other effects.',
  `status` longtext NOT NULL COMMENT 'string holding all strifer''s special abilities/status conditions (including temp power boosts)',
  `equipstatus` longtext NOT NULL COMMENT 'Hold status effects granted by equipped items',
  `bonuses` longtext NOT NULL COMMENT 'Bonuses to commands and power in general. Covers power boosts, offense boosts, defense boosts, and command bonuses',
  `equipbonuses` longtext NOT NULL COMMENT 'Contains power/command bonuses from equipped items',
  `resistances` longtext NOT NULL COMMENT 'Resistances this strifer has',
  `abilities` longtext NOT NULL COMMENT 'Stores abilities that this strifer possesses',
  `effects` longtext NOT NULL COMMENT 'Stores effects that this strifer''s basic attacks have',
  `persist` tinyint(1) NOT NULL DEFAULT '0' COMMENT 'If 1, enemy will not be deleted post-strife.'
) ENGINE=InnoDB DEFAULT CHARSET=latin1;

